import pandas as pd


def _is_null(x):
    try:
        return pd.isna(x)
    except (TypeError, ValueError):
        return x is None


def _differs(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_store = inputs['DIM_STORE'].copy()
    stg = inputs['STG_STORE_FULL'].copy()
    batch_control = inputs['BATCH_CONTROL']

    b = batch_control['batch_date'].iloc[0]

    # Step 0: DISTINCT store_id, region, format from staging, preserving
    # first-seen order (exact duplicates collapsed).
    S = stg.drop_duplicates(subset=['store_id', 'region', 'format'],
                             keep='first').reset_index(drop=True)

    working = dim_store.copy()

    # Map store_id -> row index of its current row (is_current == 1).
    current_idx = {}
    current_rows = working[working['is_current'] == 1]
    for idx, row in current_rows.iterrows():
        current_idx[row['store_id']] = idx

    new_rows = []
    s_store_ids = set()

    for _, srow in S.iterrows():
        sid = srow['store_id']
        region = srow['region']
        fmt = srow['format']
        s_store_ids.add(sid)

        if sid in current_idx:
            idx = current_idx[sid]
            crow = working.loc[idx]
            if _differs(crow['region'], region) or _differs(crow['format'], fmt):
                # Close the existing current row.
                working.at[idx, 'eff_end_date'] = b
                working.at[idx, 'is_current'] = 0
                # Insert the new current version.
                new_rows.append({
                    'store_id': sid,
                    'region': region,
                    'format': fmt,
                    'eff_start_date': b,
                    'eff_end_date': pd.NaT,
                    'is_current': 1,
                })
            # else: unchanged attributes -> no-op, no new version.
        else:
            # No current row exists: brand-new store or reactivated store.
            new_rows.append({
                'store_id': sid,
                'region': region,
                'format': fmt,
                'eff_start_date': b,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })

    # Step 2: close current rows whose store_id is absent from the snapshot.
    for sid, idx in current_idx.items():
        if sid not in s_store_ids:
            working.at[idx, 'eff_end_date'] = b
            working.at[idx, 'is_current'] = 0

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=working.columns)
        result = pd.concat([working, new_df], ignore_index=True)
    else:
        result = working.reset_index(drop=True)

    return {'dim_store_out': result}
